import{_ as t}from"./chunks/pdf-import-triage.VhDzuCgc.js";import{_ as o}from"./chunks/pdf-import-result.CIosTXBj.js";import{_ as a,o as s,c as n,a2 as r}from"./chunks/framework.CDEKL17z.js";const y=JSON.parse('{"title":"Turn a PDF into knowledge","description":"","frontmatter":{},"headers":[],"relativePath":"owner/import-a-pdf.md","filePath":"owner/import-a-pdf.md"}'),i={name:"owner/import-a-pdf.md"};function h(l,e,d,c,p,u){return s(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="turn-a-pdf-into-knowledge" tabindex="-1">Turn a PDF into knowledge <a class="header-anchor" href="#turn-a-pdf-into-knowledge" aria-label="Permalink to &quot;Turn a PDF into knowledge&quot;">​</a></h1><p>Your facts probably already live in a PDF - a customer handbook, a policy sheet, an event flyer. The assistant can&#39;t read files, only the text in its knowledge base; this tutorial walks one real PDF from &quot;attachment in your email&quot; to &quot;answers in your chat&quot;, and shows you what everything on the screen means along the way.</p><p>Ten minutes the first time, two minutes after that.</p><h2 id="before-you-start" tabindex="-1">Before you start <a class="header-anchor" href="#before-you-start" aria-label="Permalink to &quot;Before you start&quot;">​</a></h2><ul><li>You can sign in to the admin and open <strong>Tenant → Knowledge base</strong> (staff accounts can do everything in this tutorial).</li><li>You have a PDF where the <em>text is selectable</em>. Quick check: open it and try to select a sentence with your mouse. If you can&#39;t, it&#39;s a scan - photos of pages - and the importer will tell you the same thing. Re-export it from the original document, or plan to type the key facts by hand.</li></ul><h2 id="step-1-analyze-which-is-free" tabindex="-1">Step 1 - Analyze, which is free <a class="header-anchor" href="#step-1-analyze-which-is-free" aria-label="Permalink to &quot;Step 1 - Analyze, which is free&quot;">​</a></h2><p>On the Knowledge base page, find <strong>Import from a PDF</strong>, choose your file, and click <strong>Analyze PDF (free)</strong>. The button says free because it is: no AI model runs. The platform reads the text out of the file and does the mechanical cleanup itself - repeated headers and footers, page numbers, table-of-contents dot lines all go, and it tells you what it removed.</p><p><img src="'+t+'" alt="The analysis: what was read, what was removed, what the AI step would cost"></p><p>Reading this screen, top to bottom:</p><ul><li><strong>&quot;2 pages, 1,473 characters read, cleaned to 1,451 for free&quot;</strong> - the size of your file as text, and what the free cleanup already saved. With a bigger, messier PDF this line is more dramatic (&quot;Removed a repeated header/footer (40 lines)&quot;).</li><li><strong>Suggestions</strong>, when they appear, are specific to <em>your</em> file: a scanned PDF gets &quot;the bot cannot read pictures&quot;, a price-table-heavy one gets &quot;prices should come from the live tools&quot;, a very long one gets &quot;split it into one import per topic&quot;. A small clean file gets no lecture at all.</li><li><strong>The text box</strong> holds everything that survived. It&#39;s editable, and that&#39;s the point.</li><li><strong>The green line</strong> is the cost forecast for the <em>optional</em> AI step. More on it now.</li></ul><h2 id="step-2-read-the-forecast-trim-if-it-says-so" tabindex="-1">Step 2 - Read the forecast, trim if it says so <a class="header-anchor" href="#step-2-read-the-forecast-trim-if-it-says-so" aria-label="Permalink to &quot;Step 2 - Read the forecast, trim if it says so&quot;">​</a></h2><p>The estimate is a real prediction, not decoration: once the text is extracted, its length tells us the token cost of an AI pass before it runs.</p><ul><li><strong>Green - &quot;cheap, about one conversation&#39;s worth.&quot;</strong> A typical menu, flyer, or handbook lands here. Just proceed; the gauge is not asking you to do anything.</li><li><strong>Yellow - &quot;noticeable, worth trimming first.&quot;</strong> Scroll the text box and delete the sections customers never ask about - legal boilerplate, internal notes, last year&#39;s promos. Watch the estimate shrink as you cut.</li><li><strong>Red - &quot;too big for one pass, trim or split.&quot;</strong> Don&#39;t fight it: import topic by topic instead (hours in one document, policies in another). Retrieval prefers that shape anyway.</li></ul><p>Here&#39;s the part that matters more than tokens: <strong>trimming isn&#39;t about the money.</strong> Everything you keep becomes searchable knowledge, and junk that survives - table fragments, footer noise, outdated promos - can come back <em>in answers</em>. A minute of deleting here buys better replies for months.</p><h2 id="step-3-tidy-with-ai-or-skip-it" tabindex="-1">Step 3 - Tidy with AI, or skip it <a class="header-anchor" href="#step-3-tidy-with-ai-or-skip-it" aria-label="Permalink to &quot;Step 3 - Tidy with AI, or skip it&quot;">​</a></h2><p>The one paid step carries its price on the button: <strong>Tidy with AI (~581 tokens)</strong>. Click it and the model reorganizes your text into short <code>##</code> sections - one topic per heading, plain sentences - which is exactly the shape the assistant retrieves best. It rewrites structure, never facts: numbers, names, and hours stay as written, and anything unreadable is dropped rather than guessed.</p><p>If your PDF was already tidy, <strong>Skip AI, use as is</strong> does what it says and costs nothing.</p><p><img src="'+o+'" alt="After the AI pass: sectioned markdown, and the tokens actually used"></p><p>Notice the honesty line at the top: <em>estimated ~581, actually used …</em> - the forecast has to earn your trust on every run. And read the result before saving. The model organizes, but <strong>you</strong> know whether the veranda is really pet-friendly.</p><h2 id="step-4-save-then-catch-it-in-the-act" tabindex="-1">Step 4 - Save, then catch it in the act <a class="header-anchor" href="#step-4-save-then-catch-it-in-the-act" aria-label="Permalink to &quot;Step 4 - Save, then catch it in the act&quot;">​</a></h2><p>Give it a title (saving with an existing title replaces that document), click <strong>Save &amp; embed</strong>, and the content is chunked, embedded, and searchable immediately.</p><p>Now prove it works: open your chat page and ask something only the PDF knew - &quot;can I bring my dog?&quot;, &quot;do you take phone orders at 8 AM?&quot;. Then open that conversation in <strong>Conversations</strong>: the assistant&#39;s turn should carry a <strong>used tools: search_kb</strong> label, which is the knowledge-base lookup happening. That label system is explained on <a href="./day-to-day">Running it day to day</a>.</p><h2 id="when-something-s-off" tabindex="-1">When something&#39;s off <a class="header-anchor" href="#when-something-s-off" aria-label="Permalink to &quot;When something&#39;s off&quot;">​</a></h2><ul><li><strong>&quot;No selectable text / looks scanned&quot;</strong> - it&#39;s photos of pages. Re-export the source document as a PDF with real text, or paste the facts into a normal document.</li><li><strong>&quot;Too much text for one AI pass&quot;</strong> - delete more in the text box, or import in topic-sized pieces.</li><li><strong>The AI pass failed</strong> - usually the model backend having a moment; try again, or use <strong>Skip AI</strong> and tidy the headings yourself.</li><li><strong>A fact came out wrong or stale</strong> - it&#39;s a normal document now: open it under Knowledge base, fix the line, save. The answer cache clears itself on every knowledge edit, so corrections reach visitors immediately.</li></ul><p>The reference version of all this, including the retrieval rules and the CSV bulk loop, is in <a href="./../guide/knowledge-base#import-from-a-pdf">Knowledge base</a>.</p>',25)])])}const b=a(i,[["render",h]]);export{y as __pageData,b as default};
